def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w
                            and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))

    def shape(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    references = {}
    for color, cells in components:
        if color != 1:
            references.setdefault(shape(cells), color)

    out = [row[:] for row in grid]
    for color, cells in components:
        if color == 1:
            target = references.get(shape(cells))
            if target is not None:
                for r, c in cells:
                    out[r][c] = target
    return out
